// Generated by scripts/generate_capabilities.py from
// app/capabilities/*/web/help/ — DO NOT EDIT.
// The help registry: one group per topic, keyed by the canonical
// <capability>.<slug> id. Bodies are lazy ?raw imports, and helpFor
// resolves the requested locale, falling back to the source language
// with fallback set where a topic has no translation in it. A new
// topic appears here by existing, with zero generator changes.

export interface HelpTopic {
  id: string;
  capability: string;
  topic: string;
  title: string;
  surfaces: readonly string[];
  locale: string;
  fallback: boolean;
  load: () => Promise<string>;
}

export interface HelpGroup {
  id: string;
  capability: string;
  topic: string;
  surfaces: readonly string[];
  order: number;
  locales: Record<string, { title: string; load: () => Promise<string> }>;
}

export const helpGroups: readonly HelpGroup[] = [
  {
    id: "writing.editor",
    capability: "writing",
    topic: "editor",
    surfaces: ["editor"],
    order: 10,
    locales: {
      "en": { title: "The Writing Editor", load: () => import("../../../app/capabilities/writing/web/help/en/editor.md?raw").then((m) => m.default) },
    },
  },
];

export function helpFor(surface: string, locale?: string): HelpTopic[] {
  const wanted = locale ?? "en";
  return helpGroups
    .filter((group) => group.surfaces.includes(surface))
    .sort((a, b) => a.order - b.order || a.topic.localeCompare(b.topic))
    .map((group) => {
      const localized = group.locales[wanted];
      const picked = localized ?? group.locales["en"];
      return {
        id: group.id,
        capability: group.capability,
        topic: group.topic,
        title: picked.title,
        surfaces: group.surfaces,
        locale: localized ? wanted : "en",
        fallback: !localized,
        load: picked.load,
      };
    });
}
